questionvariables.text:
/* Base and Width */
l: rand_with_step(15, 40, 1);
w: rand_with_step(4, 12, 1);

/* Calculate Area */
A: l * w;

/* Teacher Answer */
ta: w;

/* Common Algebraic Mistakes for PRT */
m1: A * l;          /* Multiplied Area and length instead of dividing */
m2: (A - 2*l) / 2;  /* Confused area formula with perimeter formula */
m3: A - l;          /* Subtracted instead of dividing */
